public:
    std::string id;
    std::string username;
    std::chrono::system_clock::time_point createdAt;
    std::chrono::system_clock::time_point lastAccessed;
    std::chrono::seconds ttl;

    Session(const std::string& id, const std::string& user, std::chrono::seconds ttl = std::chrono::seconds(3600))
        : id(id), username(user), createdAt(std::chrono::system_clock::now()),
          lastAccessed(std::chrono::system_clock::now()), ttl(ttl) {}

    bool isExpired() const {
        return std::chrono::system_clock::now() > (lastAccessed + ttl);
    }

    void touch() {
        lastAccessed = std::chrono::system_clock::now();
    }
};

class SessionManager {
private:
    std::map<std::string, Session> sessions;
    std::mutex mtx;
    std::string generateSessionId() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 15);
        std::stringstream ss;
        ss << std::hex;
        for (int i = 0; i < 32; ++i) {
            ss << dis(gen);
        }
        return ss.str();
    }

public:
    std::string createSession(const std::string& username) {
        std::lock_guard<std::mutex> lock(mtx);
        std::string id = generateSessionId();
        sessions.emplace(id, Session(id, username));
        return id;
    }

    Session* getSession(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = sessions.find(id);
        if (it != sessions.end() && !it->second.isExpired()) {
            it->second.touch();
            return &it->second;
        }
        if (it != sessions.end() && it->second.isExpired()) {
            sessions.erase(it);
        }
        return nullptr;
    }

    bool destroySession(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);
        return sessions.erase(id) > 0;
    }

    void cleanupExpired() {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::system_clock::now();
        for (auto it = sessions.begin(); it != sessions.end(); ) {
            if (it->second.isExpired()) {
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
    }

    size_t count() {
        std::lock_guard<std::mutex> lock(mtx);
        return sessions.size();
    }
};

